[assembly: SuppressMessage("NDepend", "ND1804:AvoidPubliclyVisibleConstantFields", Target = "Stride.CommunityToolkit:Stride.CommunityToolkit.Engine.ScreenshotCapture.OutputPathVariable", Justification = "Environment-variable name, i.e. a contract with whoever launches the process; a consumer keeping the name it was compiled against is the correct behaviour.")]
